"""End-to-end tests for the expand-contract rename orders.state -> orders.status.

Flow:
  1. seed 100 orders
  2. phase A: expand + dual-write triggers
  3. mixed old-code / new-code traffic (including recursive_triggers=ON to
     prove the WHEN guards prevent trigger recursion)
  4. assert state == status on every row
  5. phase B: contract via table rebuild
  6. assert final schema, data integrity, and that old-style writes fail
"""

import sqlite3

import pytest

from migration import (
    columns_of,
    create_schema,
    phase_a,
    phase_b,
    seed_orders,
    trigger_names,
)

EXPECTED_COLUMNS_B = ["id", "customer", "amount", "status", "created_at"]

# id -> (customer, amount, status) spot checks, deterministic from seeding
SPOT_ROWS = {
    1: ("customer-001", 10.0, "pending"),
    25: ("customer-025", round(10.0 + (24 % 17) * 3.5, 2), "paid"),
    50: ("customer-050", round(10.0 + (49 % 17) * 3.5, 2), "shipped"),
    77: ("customer-077", round(10.0 + (76 % 17) * 3.5, 2), "cancelled"),
    100: ("customer-100", round(10.0 + (99 % 17) * 3.5, 2), "delivered"),
}


@pytest.fixture()
def db():
    conn = sqlite3.connect(":memory:")
    conn.row_factory = sqlite3.Row
    create_schema(conn)
    seed_orders(conn, n=100)
    yield conn
    conn.close()


@pytest.fixture()
def expanded(db):
    """Database seeded and migrated through phase A."""
    phase_a(db)
    return db


def synced_count(conn):
    """Rows where the two columns disagree (null-safe comparison)."""
    return conn.execute(
        "SELECT COUNT(*) FROM orders WHERE state IS NOT status"
    ).fetchone()[0]


# ---------------------------------------------------------------------------
# Phase A behaviour
# ---------------------------------------------------------------------------

class TestPhaseA:
    def test_both_columns_exist_and_backfilled(self, expanded):
        cols = columns_of(expanded)
        assert "state" in cols and "status" in cols

        row = expanded.execute(
            "SELECT COUNT(*) FROM orders WHERE status IS NULL OR status IS NOT state"
        ).fetchone()
        assert row[0] == 0

    def test_all_four_triggers_installed(self, expanded):
        assert {"orders_ai_state", "orders_ai_status",
                "orders_au_state", "orders_au_status"} <= trigger_names(expanded)


# ---------------------------------------------------------------------------
# Mixed live-ish traffic during the dual-write window
# ---------------------------------------------------------------------------

class TestMixedTraffic:
    def test_mixed_writers_keep_columns_in_sync(self, expanded):
        conn = expanded
        conn.execute("PRAGMA recursive_triggers = ON")  # stress the WHEN guards

        # old-code writers: touch ONLY legacy `state`
        for i in range(1, 51):
            conn.execute(
                "UPDATE orders SET state = 'old-code-' || ? WHERE id = ?", (str(i), i)
            )
        # new-code writers: touch ONLY `status`
        for i in range(51, 101):
            conn.execute(
                "UPDATE orders SET status = 'new-code-' || ? WHERE id = ?", (str(i), i)
            )

        # old-code inserts: provide only `state`
        conn.execute(
            "INSERT INTO orders (customer, amount, state) VALUES ('old-ins', 1.5, 'pending')"
        )
        # new-code inserts: provide only `status`
        conn.execute(
            "INSERT INTO orders (customer, amount, status) VALUES ('new-ins', 2.5, 'shipped')"
        )

        assert synced_count(conn) == 0

    def test_values_landed_where_expected(self, expanded):
        conn = expanded
        assert conn.execute(
            "SELECT state FROM orders WHERE id = 7"
        ).fetchone()[0] == "old-code-7"
        assert conn.execute(
            "SELECT status FROM orders WHERE id = 60"
        ).fetchone()[0] == "new-code-60"

    def test_no_recursion_with_recursive_triggers_on(self, expanded):
        conn = expanded
        conn.execute("PRAGMA recursive_triggers = ON")
        conn.execute("UPDATE orders SET state = 'flip' WHERE id = 3")
        conn.execute("UPDATE orders SET status = 'flop' WHERE id = 4")
        assert synced_count(conn) == 0


# ---------------------------------------------------------------------------
# Phase B behaviour
# ---------------------------------------------------------------------------

@pytest.fixture()
def contracted(expanded):
    """Phase A -> mixed traffic -> phase B."""
    conn = expanded
    conn.execute("PRAGMA recursive_triggers = ON")
    conn.execute("UPDATE orders SET state = 'old-code-final' WHERE id = 42")
    conn.execute("UPDATE orders SET status = 'new-code-final' WHERE id = 99")
    phase_b(conn)
    return conn


class TestPhaseB:
    def test_final_schema_has_only_status(self, contracted):
        cols = contracted.columns_of if False else columns_of(contracted)
        assert cols == EXPECTED_COLUMNS_B
        assert "state" not in cols

    def test_triggers_dropped(self, contracted):
        assert trigger_names(contracted).isdisjoint(
            {"orders_ai_state", "orders_ai_status",
             "orders_au_state", "orders_au_status"}
        )

    def test_row_count_preserved(self, contracted):
        assert contracted.execute("SELECT COUNT(*) FROM orders").fetchone()[0] == 102

    def test_exact_rows_intact(self, contracted):
        for oid, (customer, amount, status) in SPOT_ROWS.items():
            row = contracted.execute(
                "SELECT customer, amount, status FROM orders WHERE id = ?", (oid,)
            ).fetchone()
            assert row is not None, f"row {oid} missing after rebuild"
            assert row["customer"] == customer
            assert abs(row["amount"] - amount) < 1e-9
            assert row["status"] == status

    def test_synced_traffic_rows_survive_rebuild(self, contracted):
        assert (
            contracted.execute(
                "SELECT status FROM orders WHERE id = 42"
            ).fetchone()["status"]
            == "old-code-final"
        )
        assert (
            contracted.execute(
                "SELECT status FROM orders WHERE id = 99"
            ).fetchone()["status"]
            == "new-code-final"
        )

    def test_old_style_writes_now_fail(self, contracted):
        with pytest.raises(sqlite3.OperationalError):
            contracted.execute(
                "UPDATE orders SET state = 'boom' WHERE id = 1"
            )
        with pytest.raises(sqlite3.OperationalError):
            contracted.execute(
                "INSERT INTO orders (customer, amount, state) VALUES ('x', 1, 'pending')"
            )

    def test_new_style_write_still_works(self, contracted):
        contracted.execute("INSERT INTO orders (customer, amount, status) VALUES ('post-b', 9.9, 'paid')")
        row = contracted.execute(
            "SELECT status FROM orders WHERE customer = 'post-b'"
        ).fetchone()
        assert row["status"] == "paid"

    def test_index_recreated_on_status(self, contracted):
        idx = [
            r["name"]
            for r in contracted.execute(
                "SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='orders'"
            )
        ]
        assert "idx_orders_status" in idx

